={{
  (() => {
    // 1. Безопасно достаем контекст без падения на невыполненных ветках
    let ctx = null;
    try {
      const carouselDraft = $('[DB] Загрузить черновик карусели').all();
      if (carouselDraft.length > 0) ctx = carouselDraft[0].json;
    } catch (e) {}

    if (!ctx) {
      try {
        const singleContext = $('[DB] Загрузить контекст и токен').all();
        if (singleContext.length > 0) ctx = singleContext[0].json;
      } catch (e) {}
    }

    const platformNames = {
      instagram: 'Instagram',
      vk: 'ВКонтакте',
      youtube: 'YouTube',
      telegram: 'Telegram'
    };

    const formatNames = {
      reels: 'Reels',
      feed_post: 'поста в ленту',
      carousel: 'карусели',
      stories: 'истории',
      shorts: 'Shorts'
    };

    const targetPlatform = ctx?.draft_data?.target_platform;
    const targetFormat = ctx?.draft_data?.target_format;
    const platform = platformNames[targetPlatform] || 'Instagram';
    const format = formatNames[targetFormat] || 'материала';

    // 2. Распознаем ошибку из контракта адаптера (error_message)
    let reason = 'Произошла непредвиденная ошибка на стороне сервиса.';

    if ($json.error_message) {
      reason = $json.error_message;
    } else if ($json.status_code === 'ERROR') {
      reason = 'Серверы площадки отклонили медиафайл (проверьте формат, пропорции или размер).';
    } else if ($json.status_code === 'IN_PROGRESS') {
      reason = 'Превышено время ожидания обработки на серверах площадки (таймаут кодирования).';
    } else if ($json.error?.message) {
      reason = $json.error.message;
    } else if ($json.errorMessage) {
      reason = $json.errorMessage;
    }

    return `❌ Не удалось опубликовать ${format} в ${platform}.\n\nПричина: ${reason}`;
  })()
}}

=🎞 Сборка карусели Instagram ({{ $('[DB] Актуализировать счетчик карусели').item.json.items_count }}/10)

Состав публикации:
{{ ($('[DB] Актуализировать счетчик карусели').item.json.draft_data?.items || []).map((item, idx) => `${idx + 1}. ${item.type === 'photo' ? 'Фотография 🖼' : 'Видеоролик 🎬'}`).join('\n') }}

📝 Описание: {{ $('[DB] Актуализировать счетчик карусели').item.json.current_caption ? `«${$('[DB] Актуализировать счетчик карусели').item.json.current_caption}»` : 'отсутствует (будет опубликовано без текста)' }}

{{
  (() => {
    const data = $('[DB] Актуализировать счетчик карусели').item.json;
    const count = data.items_count || 0;
    const limitExceeded = data.draft_data?.limit_exceeded === true;

    if (limitExceeded) {
      return '⚠️ Внимание: достигнут лимит Instagram (максимум 10 файлов)!\nФайл(ы) сверх лимита не добавлены.\n\n✅ Карусель укомплектована и готова к публикации:';
    }

    if (count === 0) {
      return '⚠️ Для публикации карусели добавьте минимум 2 файла (фотографии или видео).';
    } else if (count === 1) {
      return '⚠️ Для публикации карусели добавьте ещё минимум 1 файл.';
    } else if (count === 10) {
      return '🎉 Карусель заполнена до максимума (10/10)!\nНовые файлы больше не принимаются. Нажмите кнопку публикации:';
    } else {
      return '✅ Карусель готова к публикации!\n(Вы можете отправить ещё файлы или нажать кнопку ниже)';
    }
  })()
}}

