parameters.query:
INSERT INTO publications (
    user_id,
    platform_account_id,
    platform,
    media_type,
    media_file_id,
    caption,
    media_payload,
    status,
    platform_post_id,
    published_at
) VALUES (
    -- user_id (chat_id)
    {{
      $('[DB] Загрузить черновик карусели').isExecuted
        ? $('[DB] Загрузить черновик карусели').item.json.chat_id
        : $('[DB] Загрузить контекст и токен').item.json.chat_id
    }}::bigint,

    -- platform_account_id
    {{
      $('[DB] Загрузить черновик карусели').isExecuted
        ? $('[DB] Загрузить черновик карусели').item.json.internal_platform_id
        : $('[DB] Загрузить контекст и токен').item.json.internal_platform_id
    }},

    'instagram',

    -- media_type / format
    '{{
      $('[DB] Загрузить черновик карусели').isExecuted
        ? "carousel"
        : ($('[DB] Загрузить контекст и токен').item.json.draft_data?.target_format || "feed_post")
    }}',

    -- media_file_id (для карусели берём первый слайд, для одиночных - исходный file_id)
    '{{
      $('[DB] Загрузить черновик карусели').isExecuted
        ? ($('[DB] Загрузить черновик карусели').item.json.draft_data?.items[0]?.file_id || "")
        : ($('[DB] Загрузить контекст и токен').item.json.file_id || "")
    }}',

    -- caption
    '{{
      (
        $('[DB] Загрузить черновик карусели').isExecuted
          ? ($('[DB] Загрузить черновик карусели').item.json.draft_data?.caption || "")
          : ($('[DB] Загрузить контекст и токен').item.json.caption || "")
      ).replace(/'/g, "''")
    }}',

    -- media_payload
    '{{
      JSON.stringify(
        $('[DB] Загрузить черновик карусели').isExecuted
          ? ($('[DB] Загрузить черновик карусели').item.json.draft_data?.items || [])
          : [
              {
                index: 1,
                type: $('[DB] Загрузить контекст и токен').item.json.incoming_type || "photo",
                file_id: $('[DB] Загрузить контекст и токен').item.json.file_id
              }
            ]
      ).replace(/'/g, "''")
    }}'::jsonb,

    'published',

    -- platform_post_id из контракта адаптера
    '{{ $json.platform_post_id }}',

    CURRENT_TIMESTAMP
)
RETURNING *;

